{"file_path": "src/lib/wordpress.ts", "initial_content": "import axios from 'axios'
import type { WordPressPost, SimplifiedPost, WordPressCategory, WordPressTag } from '@/types/wordpress'

const WP_API_URL = process.env.NEXT_PUBLIC_WORDPRESS_API_URL || ''

// Cache duration in seconds
const CACHE_DURATION = 300 // 5 minutes

let postsCache: { data: SimplifiedPost[], timestamp: number } | null = null

/**
 * Fetch posts from WordPress REST API
 */
export async function getPosts(params?: {
  per_page?: number
  page?: number
  categories?: string
  tags?: string
  search?: string
}): Promise<SimplifiedPost[]> {
  // Check cache
  if (postsCache && Date.now() - postsCache.timestamp < CACHE_DURATION * 1000) {
    return postsCache.data
  }

  try {
    const queryParams = new URLSearchParams({
      _embed: 'true',
      per_page: String(params?.per_page || 10),
      page: String(params?.page || 1),
      ...(params?.categories && { categories: params.categories }),
      ...(params?.tags && { tags: params.tags }),
      ...(params?.search && { search: params.search }),
    })

    const response = await axios.get<WordPressPost[]>(
      `${WP_API_URL}/posts?${queryParams.toString()}`
    )

    const simplifiedPosts = response.data.map(post => simplifyPost(post))

    // Update cache
    postsCache = {
      data: simplifiedPosts,
      timestamp: Date.now()
    }

    return simplifiedPosts
  } catch (error) {
    console.error('Error fetching posts from WordPress:', error)
    return []
  }
}

/**
 * Fetch a single post by slug
 */
export async function getPostBySlug(slug: string): Promise<SimplifiedPost | null> {
  try {
    const response = await axios.get<WordPressPost[]>(
      `${WP_API_URL}/posts?slug=${slug}&_embed=true`
    )

    if (response.data.length === 0) {
      return null
    }

    return simplifyPost(response.data[0])
  } catch (error) {
    console.error('Error fetching post by slug:', error)
    return null
  }
}

/**
 * Fetch categories
 */
export async function getCategories(): Promise<WordPressCategory[]> {
  try {
    const response = await axios.get<WordPressCategory[]>(
      `${WP_API_URL}/categories?per_page=100`
    )
    return response.data
  } catch (error) {
    console.error('Error fetching categories:', error)
    return []
  }
}

/**
 * Fetch tags
 */
export async function getTags(): Promise<WordPressTag[]> {
  try {
    const response = await axios.get<WordPressTag[]>(
      `${WP_API_URL}/tags?per_page=100`
    )
    return response.data
  } catch (error) {
    console.error('Error fetching tags:', error)
    return []
  }
}

/**
 * Convert WordPress post to simplified format
 */
function simplifyPost(post: WordPressPost): SimplifiedPost {
  const author = post._embedded?.author?.[0]
  const featuredMedia = post._embedded?.['wp:featuredmedia']?.[0]
  const categories = post._embedded?.['wp:term']?.[0] || []
  const tags = post._embedded?.['wp:term']?.[1] || []

  return {
    id: post.id,
    title: post.title.rendered,
    slug: post.slug,
    excerpt: stripHtml(post.excerpt.rendered),
    content: post.content.rendered,
    date: post.date,
    author: {
      name: author?.name || 'Anonymous',
      avatar: author?.avatar_urls?.['96'] || '',
    },
    featuredImage: featuredMedia ? {
      url: featuredMedia.source_url,
      alt: featuredMedia.alt_text || post.title.rendered,
    } : undefined,
    categories: categories.map((cat: any) => cat.name),
    tags: tags.map((tag: any) => tag.name),
  }
}

/**
 * Strip HTML tags from string
 */
function stripHtml(html: string): string {
  return html.replace(/<[^>]*>/g, '').trim()
}

/**
 * Get all post slugs for static generation
 */
export async function getAllPostSlugs(): Promise<string[]> {
  try {
    const response = await axios.get<WordPressPost[]>(
      `${WP_API_URL}/posts?per_page=100&_fields=slug`
    )
    return response.data.map(post => post.slug)
  } catch (error) {
    console.error('Error fetching post slugs:', error)
    return []
  }
}
"}

{"file_path": "src/lib/seo-config.ts", "initial_content": "import { DefaultSeoProps } from 'next-seo'

const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL || 'https://yourusername.github.io'
const SITE_NAME = process.env.NEXT_PUBLIC_SITE_NAME || 'AI Blog Platform'
const SITE_DESCRIPTION = process.env.NEXT_PUBLIC_SITE_DESCRIPTION || 'AI-powered blog for Philippine creators'

export const SEO_CONFIG: DefaultSeoProps = {
  titleTemplate: `%s | ${SITE_NAME}`,
  defaultTitle: SITE_NAME,
  description: SITE_DESCRIPTION,
  canonical: SITE_URL,
  openGraph: {
    type: 'website',
    locale: 'en_US',
    url: SITE_URL,
    siteName: SITE_NAME,
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
    images: [
      {
        url: `${SITE_URL}/og-image.jpg`,
        width: 1200,
        height: 630,
        alt: SITE_NAME,
        type: 'image/jpeg',
      },
    ],
  },
  twitter: {
    handle: '@yourusername',
    site: '@yourusername',
    cardType: 'summary_large_image',
  },
  additionalMetaTags: [
    {
      name: 'viewport',
      content: 'width=device-width, initial-scale=1',
    },
    {
      name: 'keywords',
      content: 'AI, blog, Philippines, content creation, SEO, monetization',
    },
    {
      name: 'author',
      content: SITE_NAME,
    },
  ],
  additionalLinkTags: [
    {
      rel: 'icon',
      href: '/favicon.ico',
    },
    {
      rel: 'apple-touch-icon',
      href: '/apple-touch-icon.png',
      sizes: '180x180',
    },
    {
      rel: 'manifest',
      href: '/site.webmanifest',
    },
  ],
}

/**
 * Generate JSON-LD structured data for an article
 */
export function generateArticleJsonLd(article: {
  title: string
  description: string
  url: string
  imageUrl?: string
  datePublished: string
  dateModified?: string
  authorName: string
  authorUrl?: string
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: article.title,
    description: article.description,
    image: article.imageUrl || `${SITE_URL}/og-image.jpg`,
    datePublished: article.datePublished,
    dateModified: article.dateModified || article.datePublished,
    author: {
      '@type': 'Person',
      name: article.authorName,
      url: article.authorUrl || SITE_URL,
    },
    publisher: {
      '@type': 'Organization',
      name: SITE_NAME,
      logo: {
        '@type': 'ImageObject',
        url: `${SITE_URL}/logo.png`,
      },
    },
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': article.url,
    },
  }
}

/**
 * Generate JSON-LD structured data for blog posting
 */
export function generateBlogPostingJsonLd(post: {
  title: string
  excerpt: string
  url: string
  imageUrl?: string
  publishDate: string
  modifiedDate?: string
  authorName: string
  keywords?: string[]
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: post.title,
    description: post.excerpt,
    image: post.imageUrl,
    datePublished: post.publishDate,
    dateModified: post.modifiedDate || post.publishDate,
    author: {
      '@type': 'Person',
      name: post.authorName,
    },
    publisher: {
      '@type': 'Organization',
      name: SITE_NAME,
      logo: {
        '@type': 'ImageObject',
        url: `${SITE_URL}/logo.png`,
      },
    },
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': post.url,
    },
    keywords: post.keywords?.join(', '),
  }
}

/**
 * Generate breadcrumb JSON-LD
 */
export function generateBreadcrumbJsonLd(items: Array<{ name: string; url: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: item.url,
    })),
  }
}
"}

{"file_path": "src/lib/ai-helpers.ts", "initial_content": "import OpenAI from 'openai'
import type { 
  ContentIdeaRequest, 
  ContentIdea, 
  SEOSuggestion, 
  TagSuggestion,
  TranslationRequest,
  ContentSummary 
} from '@/types/ai'

const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
})

/**
 * Generate content ideas based on topic and keywords
 */
export async function generateContentIdeas(
  request: ContentIdeaRequest
): Promise<ContentIdea[]> {
  const prompt = `Generate 3 blog post ideas for Philippine creators about ${request.topic || 'technology and AI'}.

Language: ${request.language === 'fil' ? 'Filipino/Tagalog' : 'English'}
Tone: ${request.tone}
Keywords to include: ${request.keywords?.join(', ') || 'N/A'}

For each idea, provide:
1. A compelling title
2. A brief description (2-3 sentences)
3. 5 relevant keywords
4. An outline with 4-5 main points

Format as JSON array.`

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4-turbo-preview',
      messages: [
        {
          role: 'system',
          content: 'You are a content strategist for Philippine creators, specializing in SEO-optimized blog content.',
        },
        {
          role: 'user',
          content: prompt,
        },
      ],
      response_format: { type: 'json_object' },
    })

    const response = JSON.parse(completion.choices[0].message.content || '{}')
    return response.ideas || []
  } catch (error) {
    console.error('Error generating content ideas:', error)
    return []
  }
}

/**
 * Generate SEO-optimized title and meta description
 */
export async function generateSEOSuggestions(
  content: string,
  currentTitle?: string
): Promise<SEOSuggestion> {
  const prompt = `Analyze this blog post content and generate SEO-optimized suggestions for Philippine audience:

Content: ${content.substring(0, 1000)}...
Current Title: ${currentTitle || 'None'}

Provide:
1. An SEO-optimized title (50-60 characters)
2. Meta description (150-160 characters)
3. 5-7 relevant keywords
4. URL slug
5. Focus keyphrase

Format as JSON.`

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4-turbo-preview',
      messages: [
        {
          role: 'system',
          content: 'You are an SEO expert specializing in Philippine market optimization.',
        },
        {
          role: 'user',
          content: prompt,
        },
      ],
      response_format: { type: 'json_object' },
    })

    const response = JSON.parse(completion.choices[0].message.content || '{}')
    return response
  } catch (error) {
    console.error('Error generating SEO suggestions:', error)
    return {
      title: currentTitle || '',
      metaDescription: '',
      keywords: [],
      slug: '',
      focusKeyphrase: '',
    }
  }
}

/**
 * Auto-generate tags for content
 */
export async function generateTags(content: string): Promise<TagSuggestion[]> {
  const prompt = `Analyze this content and suggest relevant tags for categorization:

Content: ${content.substring(0, 1500)}...

Provide 8-10 tags with:
- tag name
- confidence score (0-1)
- category (e.g., 'technology', 'business', 'lifestyle', 'AI', 'Philippines')

Focus on Philippine context and local relevance. Format as JSON array.`

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4-turbo-preview',
      messages: [
        {
          role: 'system',
          content: 'You are a content categorization expert for Philippine digital content.',
        },
        {
          role: 'user',
          content: prompt,
        },
      ],
      response_format: { type: 'json_object' },
    })

    const response = JSON.parse(completion.choices[0].message.content || '{}')
    return response.tags || []
  } catch (error) {
    console.error('Error generating tags:', error)
    return []
  }
}

/**
 * Translate content between English and Filipino
 */
export async function translateContent(
  request: TranslationRequest
): Promise<string> {
  const prompt = `Translate the following text from ${request.from === 'en' ? 'English' : 'Filipino/Tagalog'} to ${request.to === 'en' ? 'English' : 'Filipino/Tagalog'}:

${request.text}

Maintain the tone, cultural context, and ensure natural-sounding translation appropriate for Philippine audience.`

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4-turbo-preview',
      messages: [
        {
          role: 'system',
          content: 'You are a professional translator specializing in English-Filipino translation with deep understanding of Philippine culture.',
        },
        {
          role: 'user',
          content: prompt,
        },
      ],
    })

    return completion.choices[0].message.content || ''
  } catch (error) {
    console.error('Error translating content:', error)
    return request.text
  }
}

/**
 * Generate content summary for social sharing
 */
export async function generateContentSummary(
  content: string
): Promise<ContentSummary> {
  const wordCount = content.split(/\s+/).length
  const readingTime = Math.ceil(wordCount / 200) // Average reading speed

  const prompt = `Create a summary of this blog post for social media sharing:

Content: ${content.substring(0, 2000)}...

Provide:
1. A concise summary (2-3 sentences)
2. 3-5 key points (bullet points)
3. A shareable tweet (max 280 characters with relevant hashtags)

Format as JSON.`

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4-turbo-preview',
      messages: [
        {
          role: 'system',
          content: 'You are a social media expert creating engaging summaries for Philippine audience.',
        },
        {
          role: 'user',
          content: prompt,
        },
      ],
      response_format: { type: 'json_object' },
    })

    const response = JSON.parse(completion.choices[0].message.content || '{}')
    return {
      summary: response.summary || '',
      keyPoints: response.keyPoints || [],
      readingTime,
      shareableTweet: response.shareableTweet || '',
    }
  } catch (error) {
    console.error('Error generating content summary:', error)
    return {
      summary: '',
      keyPoints: [],
      readingTime,
      shareableTweet: '',
    }
  }
}
"}

{"file_path": "src/lib/utils.ts", "initial_content": "import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Merge Tailwind CSS classes
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Format date to readable string
 */
export function formatDate(date: string | Date): string {
  const d = new Date(date)
  return new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  }).format(d)
}

/**
 * Calculate reading time
 */
export function calculateReadingTime(text: string): number {
  const wordsPerMinute = 200
  const wordCount = text.split(/\s+/).length
  return Math.ceil(wordCount / wordsPerMinute)
}

/**
 * Truncate text to specified length
 */
export function truncateText(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text
  return text.substring(0, maxLength).trim() + '...'
}

/**
 * Convert string to slug
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim()
}

/**
 * Format currency for Philippine Peso
 */
export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-PH', {
    style: 'currency',
    currency: 'PHP',
  }).format(amount)
}

/**
 * Extract domain from URL
 */
export function extractDomain(url: string): string {
  try {
    const urlObj = new URL(url)
    return urlObj.hostname
  } catch {
    return url
  }
}

/**
 * Validate email address
 */
export function isValidEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  return emailRegex.test(email)
}

/**
 * Generate random ID
 */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/**
 * Debounce function
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null
  return (...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }
}

/**
 * Copy text to clipboard
 */
export async function copyToClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch (error) {
    console.error('Failed to copy to clipboard:', error)
    return false
  }
}
"}

