        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ topic, language, tone }),
      })

      const data = await response.json()
      setIdeas(data.ideas || [])
    } catch (error) {
      console.error('Error generating ideas:', error)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Card>
